package ru.eclipsru.mikapital;
import android.content.Context;
import android.os.Handler;
import android.os.Looper;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPInputStream;

public final class Updater {
  public static final String REPO="https://github.com/eclipsru/Mi-Kapital";
  private final Context context; private final NativeStore store; private final Handler main=new Handler(Looper.getMainLooper());
  private volatile JSONObject state; private volatile JSONObject pending; private volatile boolean busy;
  public Updater(Context context,NativeStore store){this.context=context;this.store=store;state=info();}
  public JSONObject info(){try{JSONObject value=new JSONObject();value.put("platform","android");value.put("phase","idle");value.put("version",activeVersion());value.put("shellVersion",String.valueOf(BuildConfig.SHELL_VERSION));value.put("mode","files");value.put("percent",0);value.put("transferred",0);value.put("total",0);value.put("packaged",true);return value;}catch(Exception e){throw new RuntimeException(e);}}
  private void patch(JSONObject values)throws Exception{Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();state.put(key,values.get(key));}emit();}
  private void emit(){String json=state.toString();main.post(()->{if(context instanceof MainActivity)((MainActivity)context).evaluate("window.dispatchEvent(new CustomEvent('mi-kapital-update',{detail:"+json+"}))");});}
  public String stateJson(){return state.toString();}
  private static int compare(String a,String b){String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){int result=Integer.compare(Integer.parseInt(x[i]),Integer.parseInt(y[i]));if(result!=0)return result;}return 0;}
  public String activeVersion(){try{JSONObject pointer=new JSONObject(NativeStore.read(store.file("updates/active.json")));String version=pointer.getString("version");if(pointer.optBoolean("quarantined")||pointer.getInt("shellVersion")!=BuildConfig.SHELL_VERSION||compare(version,BuildConfig.VERSION_NAME)<=0)return BuildConfig.VERSION_NAME;File root=new File(store.file("updates/bundles"),version);JSONObject manifest=new JSONObject(NativeStore.read(new File(root,"manifest.json")));if(validate(manifest,version))return version;}catch(Exception ignored){}return BuildConfig.VERSION_NAME;}
  public File activeRoot(){String version=activeVersion();return version.equals(BuildConfig.VERSION_NAME)?null:new File(store.file("updates/bundles"),version+"/dist");}
  private boolean validate(JSONObject manifest,String version)throws Exception{if(!manifest.getString("version").equals(version)||!manifest.getString("tag").equals("v"+version))return false;JSONArray files=manifest.getJSONArray("files");Set<String> paths=new HashSet<>();long total=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String path=f.getString("path");if(path.startsWith("/")||path.contains("..")||path.contains("\\")||!paths.add(path)||!f.getString("sha256").matches("[a-f0-9]{64}")||!f.getString("asset").equals("update-"+f.getString("sha256")+".gz"))return false;total+=f.getLong("size");if(f.getLong("size")>20000000)return false;}return paths.contains("index.html")&&total<=80000000;}
  private byte[] download(String address)throws Exception{return download(address,0);}
  private byte[] download(String address,int redirects)throws Exception{if(redirects>6)throw new IOException("Too many redirects");URL url=new URL(address);if(!url.getProtocol().equals("https")||!(url.getHost().equals("github.com")||url.getHost().endsWith(".githubusercontent.com")))throw new IOException("Untrusted update host");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setRequestProperty("User-Agent","Mi-Kapital-Android/2");int code=connection.getResponseCode();if(code>=300&&code<400){String location=connection.getHeaderField("Location");connection.disconnect();return download(new URL(url,location).toString(),redirects+1);}if(code!=200){connection.disconnect();throw new IOException("GitHub HTTP "+code);}try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>20000000)throw new IOException("Update too large");out.write(buf,0,n);}return out.toByteArray();}finally{connection.disconnect();}}
  private Map<String,File> known()throws Exception{Map<String,File> result=new HashMap<>();File cache=store.file("updates/cache");File[] cached=cache.listFiles();if(cached!=null)for(File f:cached)if(f.getName().matches("[a-f0-9]{64}")&&NativeStore.hash(Files.readAllBytes(f.toPath())).equals(f.getName()))result.put(f.getName(),f);File root=activeRoot();if(root!=null)collect(root,"",result);else{JSONObject builtin=new JSONObject(NativeStore.read(context.getAssets().open("builtin.json")));JSONArray files=builtin.getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String sha=f.getString("sha256");if(result.containsKey(sha))continue;File temp=store.file("updates/cache/"+sha);try(InputStream in=context.getAssets().open("web/"+f.getString("path"));OutputStream out=new FileOutputStream(temp)){byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}if(!NativeStore.hash(Files.readAllBytes(temp.toPath())).equals(sha))throw new IOException("Built-in asset checksum");result.put(sha,temp);}}return result;}
  private void collect(File root,String relative,Map<String,File> result)throws Exception{for(File f:root.listFiles()){String path=relative.isEmpty()?f.getName():relative+"/"+f.getName();if(f.isDirectory())collect(f,path,result);else result.put(NativeStore.hash(Files.readAllBytes(f.toPath())),f);}}
  public void check(){if(busy)return;busy=true;new Thread(()->{try{patch(info().put("phase","checking"));JSONObject manifest=new JSONObject(new String(download(REPO+"/releases/latest/download/update-manifest.json"),"UTF-8"));String version=manifest.getString("version");if(!version.matches("\\d+\\.\\d+\\.\\d+")||!validate(manifest,version))throw new IOException("Неверный манифест");if(manifest.optInt("androidShellVersion",1)>BuildConfig.SHELL_VERSION){patch(info().put("phase","ready").put("mode","native").put("targetVersion",version).put("message","Для этой версии нужен новый APK. Данные сохранятся."));busy=false;return;}if(compare(version,activeVersion())<=0){patch(info().put("phase","idle").put("checkedAt",new Date().toInstant().toString()).put("message","У вас актуальная версия"));busy=false;return;}Map<String,File> known=known();JSONArray files=manifest.getJSONArray("files");List<JSONObject> missing=new ArrayList<>();long total=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(!known.containsKey(f.getString("sha256"))){missing.add(f);total+=f.getLong("size");}}patch(info().put("phase","downloading").put("targetVersion",version).put("files",missing.size()).put("total",total));long transferred=0;for(JSONObject f:missing){byte[] compressed=download(REPO+"/releases/download/"+manifest.getString("tag")+"/"+f.getString("asset"));ByteArrayOutputStream plain=new ByteArrayOutputStream();try(GZIPInputStream gzip=new GZIPInputStream(new ByteArrayInputStream(compressed))){byte[]buf=new byte[8192];int n;while((n=gzip.read(buf))!=-1){if(plain.size()+n>20000000)throw new IOException("Unpacked file too large");plain.write(buf,0,n);}}byte[]content=plain.toByteArray();if(content.length!=f.getInt("size")||!NativeStore.hash(content).equals(f.getString("sha256")))throw new IOException("Контрольная сумма не совпадает");File cache=store.file("updates/cache/"+f.getString("sha256"));store.atomicBytes(cache,content);known.put(f.getString("sha256"),cache);transferred+=content.length;patch(info().put("transferred",transferred).put("percent",(int)(transferred*100/Math.max(1,total))));}File target=new File(store.file("updates/bundles"),version);File staging=store.file("updates/staging-"+System.currentTimeMillis());try{for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);File dest=new File(staging,"dist/"+f.getString("path"));dest.getParentFile().mkdirs();Files.copy(known.get(f.getString("sha256")).toPath(),dest.toPath(),StandardCopyOption.REPLACE_EXISTING);}store.atomic(new File(staging,"manifest.json"),manifest.toString());NativeStore.deleteTree(target);target.getParentFile().mkdirs();Files.move(staging.toPath(),target.toPath());}finally{NativeStore.deleteTree(staging);}pending=manifest;patch(info().put("phase","ready").put("mode","files").put("percent",100).put("message",missing.isEmpty()?"Обновление уже загружено":"Загружены только изменившиеся файлы"));}catch(Exception e){try{patch(info().put("phase","error").put("message","Не удалось обновиться: "+e.getMessage()+". Рабочая версия сохранена."));}catch(Exception ignored){}}finally{busy=false;}}).start();}
  public String install(){try{if(!"ready".equals(state.getString("phase")))return "{\"ok\":false,\"message\":\"Сначала загрузите обновление\"}";if("native".equals(state.getString("mode"))){((MainActivity)context).openExternal(REPO+"/releases/latest/download/Mi-Kapital-mobile.apk");return "{\"ok\":true}";}if(pending==null)throw new IOException("Манифест не загружен");store.atomic(store.file("updates/active.json"),new JSONObject().put("version",pending.getString("version")).put("shellVersion",BuildConfig.SHELL_VERSION).put("quarantined",false).toString());pending=null;state=info();emit();main.post(()->((MainActivity)context).reload());return "{\"ok\":true}";}catch(Exception e){return "{\"ok\":false,\"message\":"+JSONObject.quote(e.getMessage())+"}";}}
}
